class Form { int choice; int accent; }
Form form = new Form();

// a GROUP = every radio bound to the SAME field, one value each
Radio a = new Radio(0, "Option A");
Radio b = new Radio(1, "Option B");
Radio c = new Radio(2, "Option C");
a.data = form.choice;
b.data = form.choice;
c.data = form.choice;

// variants are classes; accents recolor the checked ring + dot
Radio ok  = new Radio(0, "Info");   ok.Class  = "info";    ok.data  = form.accent;
Radio bad = new Radio(1, "Error");  bad.Class = "error";   bad.data = form.accent;

// disabled: drawn muted, never fires (click or keyboard)
Radio na  = new Radio(0, "N/A");    na.Disabled = true;

// each frame:
a.Render(app, 40, 80, "Option A");
b.Render(app, 40, 110, "Option B");
c.Render(app, 40, 140, "Option C");

Radio ad     = new Radio(0, "广告");     ad.data = model.howhear;
Radio friend = new Radio(1, "朋友推荐"); friend.data = model.howhear;
Radio other  = new Radio(2, "其他");     other.data = model.howhear;

// 备注只在「其他」时可编辑（每帧同步，字段保留态）：
note.Disabled = model.howhear != 2;
note.data = model.otherNote;

Radio a = new Radio(0, "每日送");
a.Bordered = true;
a.data = form.ship;
Radio b = new Radio(1, "自提");
b.Bordered = true;
b.data = form.ship;
// 语义色 + 禁用照常可用：
Radio s = new Radio(0, "成功"); s.Bordered = true; s.Class = "success";

Panel col = Panel.Column().Gap(8);
int id = WidgetId.Next();           // 每张卡一个整卡命中 id
for (int i = 0; i < 3; i = i + 1) {
    Panel card = Panel.Column();
    card.style = 0;                    // 卡片表面
    if (model.plan == i) {
        card.Plain(app.theme.bgActive); // 选中卡：内联高亮
    }
    Flex row = Flex.Wrapped().Gap(12) { Children = {
        radios[i],                         // 保留态，绑定 model.plan
        new Label { Text = titles[i] },
    } };
    card.Add(row);
    col.Add(card);
}
// 布局完成后读回卡片实际矩形（bx/by/bw/bh），把命中区注册成整卡：
// 点卡身任意位置即换选，聚焦后 Enter/Space 同样生效。
if (Ui.Activate(app, id, card.bx, card.by, card.bw, card.bh)
    && model.plan != i) {
    model.plan = i;
    app.RequestRedraw();
}

