class Prefs { bool dark; bool sync; int stage; }
Prefs prefs = new Prefs();
prefs.dark = true;
prefs.sync = false;
prefs.stage = 20;
Switch dark = new Switch();
dark.data = prefs.dark;   // two-way bool
// Naive UI style variants:
Switch tiny   = new Switch { Size = "tiny" };
Switch small  = new Switch { Size = "small" };
Switch large  = new Switch { Size = "large" };
Switch syncing = new Switch { Loading = true };  // thumb spinner
// inner content (track widens), square, custom colors:
Switch cn = new Switch { CheckedText = "开", UncheckedText = "关" };
Switch sq = new Switch { Round = false };
Switch col = new Switch { CheckedColor = 0x1677FF };
// int value axis: on means prefs.stage == 10, off writes back 10/20
Switch stage = new Switch { CheckedValue = 10, UncheckedValue = 20 };
stage.value = prefs.stage;
// each frame (dispatches its own click):
dark.Render(app, 40, 80);
cn.Render(app, 120, 80);
stage.Render(app, 260, 80);

Switch tiny   = new Switch { Size = "tiny" };
tiny.data = model.on;
Switch big    = new Switch { Class = "large" };  // class 同样生效
big.data = model.on;
Switch busy   = new Switch { Loading = true };   // thumb spinner
Switch sq     = new Switch { Round = false };    // 方形
Switch locked = new Switch();
locked.Disabled = true;

// caption reads the model field every frame:
status.Text = model.on ? "ON" : "OFF";

// 内嵌文字：轨道自动撑宽
Switch cn = new Switch { CheckedText = "开", UncheckedText = "关" };
cn.data = model.on;
// 内嵌图标（Gui.Icon 名）
Switch ico = new Switch { CheckedIcon = "check", UncheckedIcon = "close" };
// 方形 + 自定义色（0 = 跟随皮肤）
Switch sq = new Switch { Round = false, CheckedText = "开", UncheckedText = "关" };
Switch col = new Switch { CheckedColor = 0x1677FF, UncheckedColor = 0x0E9F6E };
Switch busy = new Switch { Loading = true, CheckedText = "同步" };

class Server { int stage; }   // 10 = 在线, 20 = 离线
Server srv = new Server();
srv.stage = 20;
Switch st = new Switch();
st.value = srv.stage;         // int 绑定轴
st.CheckedValue = 10;         // 哪个值算「开」
st.UncheckedValue = 20;       // 拨关写回的值
st.Change += () => {
    status.Text = Convert.ToString(srv.stage);  // 读回 10/20
};

Panel group = Panel.Column().Gap(8) { Children = {
    row("邮件提醒", alertsSwitch),
    row("每周摘要", digestSwitch),
} };

// 每帧：总开关的模型值禁用整组
master.data = model.masterOn;
group.Disabled = !model.masterOn;   // 沿树继承：子项一起置灰失效

Panel col = Panel.Column().Gap(8) { Children = {
    SettingsRow("后台同步", "改动自动上传", syncSwitch),
    SettingsRow("紧凑行距", "一屏容纳更多", compactSwitch),
    SettingsRow("公开资料", "任何人可见", publicSwitch),
} };

// 一行 = 卡片表面 + 左文右开关（grow 占位推到行尾）：
static Panel SettingsRow(string title, string desc, Switch sw) {
    Panel card = Panel.Column();
    card.style = 0;                 // 卡片表面
    Flex row = Flex.Wrapped().Gap(12) { Children = {
        new Label { Text = title },
        new Label { Class = "grow" },   // 吃掉剩余宽度
        sw,
    } };
    card.Add(row);
    return card;
}

sw.data = model.asyncOn;
// 每帧：
if (pending > 0) {
    model.asyncOn = applied;          // 回卷操作中的拨动
    pending = pending - 1;
    if (pending == 0) {
        model.asyncOn = target;       // 完成那一刻才落值
        applied = target;
        sw.Loading = false;
    }
} else if (model.asyncOn != applied) {
    target = model.asyncOn;           // 刚拨动：先按住
    model.asyncOn = applied;
    pending = 36;                     // ~0.6s
    sw.Loading = true;
}

