// column builders compose: pin, editable, per-column format, footer aggregate
List<DataColumn> cols = new List<DataColumn>{
  DataColumn.Pin(DataColumn.Text("Name", 140)),
  DataColumn.Avg(DataColumn.Editable(DataColumn.Percent(DataColumn.Numeric("Score", 90)))),
  DataColumn.Sum(DataColumn.Money(DataColumn.Numeric("Salary", 120), "$")) };
DataTableState state = new DataTableState();

// a column can be frozen to either edge: it leaves the scrolling band and
// holds its screen position while the middle columns pan underneath it.
// Totals and row actions belong on the right, where they stay reachable.
cols.Add(DataColumn.PinRight(DataColumn.Money(DataColumn.Numeric("Total", 110), "$")));
DataTable.PinColumnRight(state, cols.Count - 1);   // or at runtime
DataTable.TogglePin(state, 0);                     // none -> left -> right -> none

// appearance hook: a subclass, since Zan delegates can't capture. Return 0
// from a colour method for "no override"; return true from PaintCell to
// take the cell over completely (the canvas is clipped to it).
class Overdue : CellStyler {
    // RowBg can't see the app: resolve theme colours outside, per frame.
    int tint;
    void Retint(App app) { tint = DataTable.LerpColor(app.theme.bgPrimary, app.theme.error, 1, 6); }
    override int RowBg(DataSource src, int row) {
        if (src.CellText(row, 4) == "Overdue") { return tint; }
        return 0;
    }
    override bool PaintCell(App app, DataSource src, int row, int col,
                            int x, int y, int w, int h) { return false; }
}
Overdue styler = new Overdue();
state.styler = styler;
styler.Retint(app);   // per frame, so the tint follows the active theme

// name columns to stop hard-coding indices — a name survives
// insertion, reordering and a retitled (or translated) header
cols.Add(DataColumn.Field(DataColumn.Text("City", 110), "city"));
int ci = DataTable.Col(cols, "city");
string v = DataTable.Cell(source, cols, row, "city");
DataTable.SortByField(state, cols, "score", 2);   // 2 = descending

// rows can be added and removed, and every write is journalled: Ctrl+Z
// undoes a cell edit, an insert, a delete, or a whole paste at once.
// A source opts in by overriding CanInsert/InsertRow/RemoveRow;
// List<DataRow> already does, so the placeholder just needs enabling.
state.allowAddRow = true;          // "click to add" line under the last row
int added = DataTable.AppendRow(state, cols, source);
DataTable.DeleteSelectedRows(state, cols, source);   // Ctrl+Del
DataTable.Undo(state, cols, source);                 // Ctrl+Z

DataTable.Render(app, 40, 60, 520, 260, cols, rows, state);

// Subclass DataSource and feed cells on demand — the grid stores no
// rows, so memory is O(1) in the row count (vs ~1.8 GB for 70M string
// cells). CellNum returns the typed sort/aggregate key (no string parse).
class BigSource : DataSource {
    int rows;
    override int RowCount() { return this.rows; }
    override int CellNum(int row, int col) { return /* value */ 0; }
    override string CellText(int row, int col) { return /* text */ ""; }
}
DataTable.RenderSource(app, x, y, w, h, cols, source, state);

