FilePicker fp = new FilePicker();
// open with several extension filters:
List<FileFilter> filters = new List<FileFilter>{
    new FileFilter("Zan source (*.zan)", ".zan"),
    new FileFilter("Text (*.txt;*.md)", ".txt;.md"),
    new FileFilter("All files (*.*)", "")
};
fp.BeginOpenFileFilters("", filters, "Open file");

// in the event loop, route by the OWNING window (native hwnd) so the parent
// keeps responding while the dialog is open -- do NOT gate on fp.IsOpen():
nint evh = Window.EventHwnd();
if (fp.OwnsWindow(evh)) {
    fp.ApplyEvent(evh);
} else {
    app.ApplyEvent(evh);
}
fp.RenderWindow();
if (fp.TakeResult() == 1) {
    string path = fp.SelectedPath();
}

