save.Click += () => { Console.WriteLine("saved"); };
save.Click += Store.Commit;             // method group
// each frame:
save.Render(app, 40, 80, 120);          // fires Click on click
// remove: save.Click -= Store.Commit;

// Retained button: register the handler once, like C# OnClick += ...
Button start = new Button { Text = "Start background task", Class = "primary" };
start.Click += StartTask;        // method group (Action)

// each frame:
start.Render(app, 40, 80, 210);  // fires Click on click

static void StartTask() {
    Thread.Start(Worker);       // real OS thread
}

// Runs off the UI thread: hand results back with app.Post.
static void Worker() {
    Thread.Sleep(140);
    app.Post(() => { value.Set(value.Get() + 1); });
}

